DROP TABLE IF EXISTS `mvp_vote`;
CREATE TABLE `mvp_vote` (
  `season_year` int NOT NULL,
  `player_id` int NOT NULL,
  `rank_num` int DEFAULT NULL,
  `is_tied` tinyint(1) NOT NULL,
  `first_votes` int DEFAULT NULL,
